                    ctx.contentType("text/csv;charset=utf-8").result(report);
                } catch (Exception e) {
                    ctx.status(500).json(new ErrorResponse("ERROR", e.getMessage()));
                }
            })
            .get("/reports/revenue", ctx -> {
                try {
                    String monthStr = ctx.queryParam("month");
